def translate_word(word, lang):
    """Look up a word in the analogy vocab. Falls back to English if missing."""
    if lang == "en":
        return word
    vocab = ANALOGY_VOCAB.get(lang, {})
    return vocab.get(word, word)


def translate_syllogism_word(word, lang):
    """Look up a word in the syllogism vocab. Falls back to English if missing."""
    if lang == "en":
        return word
    vocab = SYLLOGISM_VOCAB.get(lang, {})
    return vocab.get(word, word)
